#include <stddef.h>

size_t length(const char *s)
{
    const char *start = s;
    while (*s) s++;
    return (size_t)(s - start);
}

int *find(int *begin, int *end, int value)
{
    for (int *p = begin; p != end; p++) {
        if (*p == value) return p;
    }
    return end;
}

