}

const char *last_of(const char *s, char c)
{
    const char *found = NULL;
    for (; *s; s++) {
        if (*s == c) found = s;
    }
    return found;
}

unitTests:
TEST("length by subtraction") { CHECK_EQ(length("pointer"), (size_t)7); CHECK_EQ(length(""), (size_t)0); }
TEST("finding a value") { int a[] = {4, 8, 15, 16, 23, 42}; int *end = a + 6; CHECK(find(a, end, 15) == a + 2); CHECK(find(a, end, 4) == a); CHECK(find(a, end, 42) == a + 5); CHECK(find(a, end, 99) == end); CHECK(find(a + 3, end, 8) == end); CHECK(find(a, a, 4) == a); }
TEST("copying a string") { char out[16] = "xxxxxxxxxxxxxxx"; copy_string(out, "hello"); CHECK_STR(out, "hello"); CHECK_EQ(out[5], '\0'); CHECK_EQ(out[6], 'x'); copy_string(out, ""); CHECK_STR(out, ""); }
TEST("the last occurrence") { const char *s = "banana"; CHECK(last_of(s, 'a') == s + 5); CHECK(last_of(s, 'b') == s); CHECK(last_of(s, 'z') == NULL); CHECK(last_of("", 'a') == NULL); }

